/// <reference types="jest" />
import { PDFDocument } from 'pdf-lib';

import { buildPdf } from './save';

// 8x4 px JPEG, so every page must come out twice as wide as tall.
const mockJpeg = '';

jest.mock('expo-file-system', () => {
  class File {
    async bytes() {
      return Uint8Array.from(atob(mockJpeg), (c) => c.charCodeAt(0));
    }
  }
  return { File, Directory: class {}, Paths: {} };
});
jest.mock('expo-media-library', () => ({}));

it('builds one A4-width page per JPEG with the image aspect ratio', async () => {
  const bytes = await buildPdf(['file:///a.jpg', 'file:///b.jpg', 'file:///c.jpg']);
  expect(String.fromCharCode(...bytes.slice(0, 4))).toBe('%PDF');
  const doc = await PDFDocument.load(bytes);
  expect(doc.getPageCount()).toBe(3);
  for (const page of doc.getPages()) {
    expect(page.getWidth()).toBeCloseTo(595.28, 2);
    expect(page.getHeight()).toBeCloseTo(297.64, 2);
  }
});
